// --- config init ---

#[test]
fn test_config_init_creates_file() {
    let dir = TempDir::new().unwrap();
    let config_path = dir.path().join("udex.toml");

    udex()
        .args(["config", "init", "--path", config_path.to_str().unwrap()])
        .assert()
        .success()
        .stdout(predicate::str::contains("config written to"));

    assert!(config_path.exists(), "config file should have been created");
    let content = std::fs::read_to_string(&config_path).unwrap();
    assert!(
        content.contains("bind_address"),
        "config should contain server fields"
    );
    assert!(
        content.contains("connection_url"),
        "config should contain datastore fields"
    );
    assert!(
        content.contains("jwt_public_key_path"),
        "config should contain authnz fields"
    );
}

#[test]
fn test_config_init_fails_if_file_exists() {
    let dir = TempDir::new().unwrap();
    let config_path = dir.path().join("udex.toml");
    std::fs::write(&config_path, "# existing").unwrap();

    udex()
        .args(["config", "init", "--path", config_path.to_str().unwrap()])
        .assert()
        .failure()
        .stderr(predicate::str::contains("already exists"));
}

