#[test]
fn test_config_validate_fails_for_missing_jwt_key() {
    let dir = TempDir::new().unwrap();
    let config_path = dir.path().join("udex.toml");

    // Write a config without jwt_public_key_path
    let content = r#"
[server]
bind_address = "127.0.0.1:50051"
request_timeout_secs = 30
max_connections = 1000
max_message_size_bytes = 4194304

[server.tls]
cert_path = "certs/server.crt"
key_path = "certs/server.key"

[server.authnz]
jwt_issuer = "https://auth.example.com"
jwt_audience = "udex"

[datastore]
connection_url = "postgres://localhost/udex"
max_connections = 10
min_connections = 1
connection_timeout_secs = 10
query_timeout_secs = 30
"#;
    std::fs::write(&config_path, content).unwrap();

    udex()
        .args([
            "config",
            "validate",
            "--config",
            config_path.to_str().unwrap(),
        ])
        .assert()
        .failure()
        .stderr(predicate::str::contains("jwt_public_key_path is required"));
}
